# Review package: 3e0e9c8849e96a957f072b271b670ed0ffa2bc4b..HEAD

## Commits
ffd6d7a test: pin topWords code-unit tie order

## Files changed
 test/topWords.test.js | 10 +++++++++-
 1 file changed, 9 insertions(+), 1 deletion(-)

## Diff
diff --git a/test/topWords.test.js b/test/topWords.test.js
index 46db2e7..c87f788 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -79,39 +79,47 @@ test('ranks the top four words of a passage and skips its stop words', () => {
 });

 test('folds upper and lower case into one entry', () => {
   assert.deepEqual(topWords('Éclair éclair', 5), [{ word: 'éclair', count: 2 }]);
 });

 test('folds the typographic apostrophe into the straight one', () => {
   assert.deepEqual(topWords("keeper’s keeper's", 5), [{ word: "keeper's", count: 2 }]);
 });

+test('breaks ties in code-unit order rather than locale order', () => {
+  assert.deepEqual(topWords('éclair fig', 2), [{ word: 'fig', count: 1 }, { word: 'éclair', count: 1 }]);
+});
+
 test('throws a RangeError naming the function for a bad n', () => {
   for (const bad of [undefined, NaN, '3', 1.5, -1]) {
     assert.throws(() => topWords('apple', bad), (err) => {
       assert.ok(err instanceof RangeError);
       assert.ok(err.message.startsWith('topWords:'));
       return true;
     });
   }
 });

 test('returns every distinct word when n exceeds their number', () => {
   assert.deepEqual(topWords('apple banana apple', 100), [
     { word: 'apple', count: 2 },
     { word: 'banana', count: 1 },
   ]);
 });

 test('checks the text before n', () => {
-  assert.throws(() => topWords(3, -1), TypeError);
+  assert.throws(() => topWords(3, -1), (err) => {
+    assert.ok(err instanceof TypeError);
+    assert.ok(err.message.startsWith('topWords:'));
+    return true;
+  });
 });

 test('returns fresh objects on every call', () => {
   const first = topWords('apple', 1);
   first[0].count = 99;
   first.push({ word: 'junk', count: 1 });
   assert.deepEqual(topWords('apple', 1), [{ word: 'apple', count: 1 }]);
 });

 test('keeps hyphenated compounds and contractions whole', () => {
